<template>
  <el-tabs type="border-card" style="width: 670px">
    <el-tab-pane label="IEEE">
      <div v-for="citation in citationList">{{ citation.IEEE }}</div>
    </el-tab-pane>
    <el-tab-pane label="LNCS">
      <div v-for="citation in citationList">{{ citation.SPRINGER_LECTURE_NOTES_IN_COMPUTER_SCIENCE }}</div>
    </el-tab-pane>
    <el-tab-pane label="APA">
      <div v-for="citation in citationList">{{ citation.APA }}</div>
    </el-tab-pane>
    <el-tab-pane label="HARVARD">
      <div v-for="citation in citationList">{{ citation.HARVARD1 }}</div>
    </el-tab-pane>
    <el-tab-pane label="VANCOUVER">
      <div v-for="citation in citationList">{{ citation.VANCOUVER }}</div>
    </el-tab-pane>
    <el-tab-pane label="BIBTEX">
      <div>{{ props.sources }}</div>
    </el-tab-pane>
  </el-tabs>
</template>

<script setup>
import {BibliographyTemplate} from "../common/bibliography";
import Cite from "citation-js";

// region 父组件传递的参数
const props = defineProps({
  // BibTex 格式的引用信息
  sources: {
    type: Array,
    // 测试用
    // default: ["@inproceedings{palma2015study,  title={A study on the taxonomy of service antipatterns},  author={Palma, Francis and Mohay, Naouel},  booktitle={2015 IEEE 2nd International Workshop on Patterns Promotion and Anti-patterns Prevention (PPAP)},  pages={5--8},  year={2015},  organization={IEEE}}","@article{cerny2023catalog,  title={Catalog and detection techniques of microservice anti-patterns and bad smells: A tertiary study},  author={Cerny, Tomas and Abdelfattah, Amr S and Al Maruf, Abdullah and Janes, Andrea and Taibi, Davide},  journal={Journal of Systems and Software},  volume={206},  pages={111829},  year={2023},  publisher={Elsevier}}"],
    default: () => [],
    required: true
  }
})
// console.log(props.sources)
// endregion

//region sources 解析
let citationList = []
const list = props.sources
// 遍历数组，一个 item 表示一条论文引用
list.forEach((item) => {
  // console.log(item)
  // 设置临时变量，记录所有类型的解析结果
  let citation = {
    "IEEE": "",
    "SPRINGER_LECTURE_NOTES_IN_COMPUTER_SCIENCE": "",
    "APA": "",
    "HARVARD1": "",
    "VANCOUVER": "",
    "BIBTEX": ""
  };

  // 遍历所有的类型，并解析成对应的引用格式
  for (const key in BibliographyTemplate) {
    // console.log(key)
    if (BibliographyTemplate[key] === BibliographyTemplate.BIBTEX) {
      citation[key] = new Cite(item).format("bibtex", {
        format: 'text'
      })
    } else {
      citation[key] = new Cite(item).format("bibliography", {
        format: 'text',
        template: key.toString().toLowerCase().replace(/_/g, "-"),
        lang: "en-US"
      })
    }
    // console.log(citation[key])
  }

  // 将临时变量的值汇集到待展示数组
  citationList.push(citation)
})
// console.log(citationList)
//endregion

</script>

