<template>
  <el-input
      v-on:input="searchHandler()"
      v-model="nameForSearch"
      style="width: 95%"
      size="large"
      placeholder="Please input the name of microservice bad smell"
      :suffix-icon="Search"
  />
  <div class="cards-container">
    <div v-for="item in antiPatternsShow" :key="item.id" class="box-card">
      <!--region 简介卡片-->
      <div class="name">{{ item.name }}</div>
      <div class="des"
           style="width: 96%; height: 200px; overflow: auto;
           white-space: pre-wrap; text-align: left;">
        {{ item.description }}
      </div>
      <div class="button-box">
        <div v-if="item.evidence > HIGHT" style="background-color: #EF6C00"/>
        <div v-if="item.evidence > HIGHT" style="background-color: #EF6C00"/>
        <div v-if="item.evidence > MIDDLE && item.evidence <= HIGHT" style="background-color: #FB8C00"/>
        <div v-if="item.evidence > MIDDLE && item.evidence <= HIGHT" style="background-color: #FB8C00"/>
        <div v-if="item.evidence <= MIDDLE" style="background-color: #FFCC80"/>
        <div v-if="item.evidence <= MIDDLE" style="background-color: #FFCC80"/>
        <el-button style="margin-left: 5%" @click="showDetail(item)">
          <el-icon class="icon">
            <Compass/>
          </el-icon>
        </el-button>
        <el-button style="margin-right: 5%" @click="clickToShare(item)">
          <el-icon class="icon">
            <Share/>
          </el-icon>
        </el-button>
      </div>
      <!--endregion-->
    </div>

    <!--region 详情弹窗-->
    <DetailComponent v-model="dialogTableVisible"
                     :key="refreshKey"
                     :antipattern="antipattern"
                     :relatedAntipatternList="relatedAntipatternList"
                     :copyAsJson="copyAsJson"/>
    <!--endregion-->
  </div>
</template>

<script setup>
import {Search} from '@element-plus/icons-vue'
import {ElNotification} from 'element-plus'
import {ref} from "vue";
import {listUsingGetByName} from "@/api/msdv-backend";
import DetailComponent from "./DetailComponent.vue";

// region 父组件传递的参数
const props = defineProps({
  antiPatternsAll: {
    type: Array,
    default: () => []
  }
})
// console.log("props.antiPatternsAll")
// console.log(props.antiPatternsAll)
// endregion 父组件传递的参数

// region 常量
// TODO 表示影响力等级强弱，数值是随便取的
const HIGHT = 15;
const MIDDLE = 10;
// endregion

//region 获取关联异味信息
const relatedAntipatternList = ref([]);

const getRelatedAntipatternList = async (item) => {
  // 每次查询前都先清空数据
  relatedAntipatternList.value = [];
  // 从数据库获取关联异味名称和关联关系
  let res = await listUsingGetByName(item.name);
  // 将数据库获取的数据存储到 relatedAntipatternList 变量中
  res.data?.forEach((antipatternRelationVO) => {
    relatedAntipatternList.value.push(antipatternRelationVO);
  })
}
//endregion

//region 通过弹窗显示选中的微服务异味的详细信息
const dialogTableVisible = ref(false); // 弹窗可见性
const antipattern = ref(null); // 选中的微服务异味
const refreshKey = ref(0); // 子组件状态控制变量，用于实现子组件的强制刷新，保证点击弹窗时，弹窗组件刷新
const showDetail = async (item) => {
  // 弹窗可见性设置
  dialogTableVisible.value = !dialogTableVisible.value;
  // 异味信息详情设置
  antipattern.value = item;
  // console.log(antipattern.value)
  // 关联异味信息获取
  await getRelatedAntipatternList(item);
  // 弹窗组件状态控制，以保证强制刷新
  refreshKey.value++;
}
//endregion

//region 复制微服务异味信息到剪切板
const clickToShare = async (item) => {
  // 从数据库获取关联异味名称和关联关系
  await getRelatedAntipatternList(item);

  // 临时数组，用于存储过滤后的微服务异味信息
  const filteredList = [];

  // 处理元素，只保留名称属性"relatedAntiPatternName"和关联关系属性"relation"
  relatedAntipatternList.value.forEach((item) => {
    let tmp = {
      "name": item.relatedAntiPatternName,
      "relation": item.relation
    }
    filteredList.push(tmp);
  })

  //删除 item 中的无用属性
  delete item.id;
  delete item.isDelete;

  //向 item 中增加新属性：关联异味信息
  item.relatedAntiPatterns = filteredList;

  // JSON Object → JSON String
  const json = JSON.stringify(item);

  // 复制到剪切板
  // copyAsJson(json, item.name)

  //TODO 20240322 修改：只保留 description 的值
  // 复制到剪切板
  copyAsJson(item.description, item.name)

}

// 复制到剪切板
const copyAsJson = (json, info) => {
  // console.log(json)
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(json)
        .then(() => {
          // 成功复制到剪切板
          ElNotification({
            title: '✅ ' + info + ' Copy succeed!',
            message: "📋 Microservice smell information has been copied to the clipboard！",
            position: 'bottom-right',
          })
        })
        .catch(err => {
          // 复制失败
          ElNotification({
            title: '⚠️ Copy failed!',
            message: "☎️ ️Please contact the admin！",
            position: 'bottom-right',
          })
          // console.log(err)
        });
  } else {
    unsecuredCopyToClipboard(json);
    // 成功复制到剪切板
    ElNotification({
      title: '✅ ' + info + ' Copy succeed!',
      message: "📋 Microservice smell information has been copied to the clipboard！",
      position: 'bottom-right',
    })
  }

}

function unsecuredCopyToClipboard(text) {
  const textArea = document.createElement("textarea");
  textArea.value = text;
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();
  try {
    document.execCommand('copy');
  } catch (err) {
    console.error('Unable to copy to clipboard', err);
  }
  document.body.removeChild(textArea);
}

// endregion

//region 按名匹配搜索功能
const antiPatternsShow = ref(props.antiPatternsAll)
const nameForSearch = ref();

function searchHandler() {
  // console.log("searchHandler is called!")
  // 不区分大小写
  let keyword = nameForSearch.value.toLowerCase();
  // console.log("keyword: " + keyword);
  let all = props.antiPatternsAll;
  const tmp = [];
  all.forEach(item => {
    // console.log(item.name);
    let lowerName = item.name.toLowerCase();
    if (lowerName.match(keyword)) tmp.push(item)
  })
  // console.log("筛选后：")
  // console.log(tmp)
  antiPatternsShow.value = tmp;
}
//endregion

</script>


