<template>
  <el-dialog :title="antipattern ? antipattern.name : ''"
             style="width: 850px; border-radius: 1%;">
    <el-descriptions
        class="margin-top"
        :column="1"
        border>

      <!--region 复制按钮-->
      <template #extra>
        <el-button type="primary" @click="clickToShare">
          Copy the Json File
        </el-button>
      </template>
      <!--endregion-->

      <!--region 弹窗属性-->
      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Aliases
          </div>
        </template>
        <div>{{ antipattern.aliases }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Description
          </div>
        </template>
        <div style="width:670px;height: 100px; overflow: auto;max-width: 100%;">{{ antipattern.description }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Detection
          </div>
        </template>
        <div style="width:670px;height: 100px; overflow: auto;">{{ antipattern.detection }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Consequence
          </div>
        </template>
        <div style="width:670px;height: 100px; overflow: auto;">{{ antipattern.consequences }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Cause
          </div>
        </template>
        <div style="width:670px;height: 100px; overflow: auto;">{{ antipattern.cause }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Example
          </div>
        </template>
        <div style="width:670px;height: 100px; overflow: auto;">{{ antipattern.example }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Category
          </div>
        </template>
        <div>{{ antipattern.categoryName }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Type
          </div>
        </template>
        <div>{{ antipattern.typeName }}</div>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Factor
          </div>
        </template>
        <div>{{ antipattern.evidence }}</div>
      </el-descriptions-item>

      <el-descriptions-item v-if="relatedAntipatternList.length > 0">
        <template #label>
          <div class="cell-item">Related Bad Smells</div>
        </template>
        <el-table :data="tableData" border style="width:670px">
          <el-table-column prop="name" label="Related Bad Smell Name" width="180"/>
          <el-table-column prop="description" label="Related Bad Smell Description"/>
          <el-table-column prop="relation" label="Relationship" width="180"/>
        </el-table>
      </el-descriptions-item>

      <el-descriptions-item>
        <template #label>
          <div class="cell-item">
            Sources
          </div>
        </template>
        <CitationsComponent :sources="sourceList"/>
      </el-descriptions-item>
      <!--endregion-->
    </el-descriptions>
  </el-dialog>
</template>

<script setup>
import {ElMessage} from "element-plus";
import {ref} from "vue";
import {listUsingGet} from "../api/msdv-backend";
import CitationsComponent from "@/components/CitationsComponent";

//region 父组件传递的参数
const props = defineProps({
  // 选中的微服务异味信息
  antipattern: {
    type: Object,
  },
  // 选中的微服务异味信息的关联异味信息
  relatedAntipatternList: Array,
  dialogTableVisible: {
    type: Boolean,
    default: false
  },
  // 复制到剪切板的方法
  copyAsJson: {
    type: Function,
    required: false
  },
  antiPatternsAll: {
    type: Array,
    default: () => []
  }
})
// console.log("props.antipattern")
// console.log(props.antipattern)
// console.log("props.relatedAntipatternList")
// console.log(props.relatedAntipatternList)
// console.log("props.antiPatternsAll")
// console.log(props.antiPatternsAll)
//endregion

//region JSON String → JSON Object[]
let sourceList = [];
if (props.antipattern === null || props.relatedAntipatternList === []) {
// 初始化时，父组件尚未选中 item，此时传到子组件中的数据为空数据
} else {
  try {
    //从 antipattern 中获取 sources，将其解析为 JSON Object[]
    // console.log("props.antipattern.sources")
    // console.log(props.antipattern.sources)
    sourceList = JSON.parse(props.antipattern.sources);
    // console.log("sourceList")
    // console.log(sourceList)
  } catch (error) {
    // console.log(error)
    ElMessage.error('JSON 解析失败')
  }
}
//endregion

//region 复制到剪切板
const clickToShare = () => {
  // 临时数组：记录处理后的关键异味信息
  const filteredList = [];

  // 处理元素
  // 保留名称属性"relatedAntiPatternName"和关联关系属性"relation"
  // 删除 id、isDelete、antiPatternName 等无用属性
  props.relatedAntipatternList.forEach((item) => {
    let tmp = {
      "name": item.relatedAntiPatternName,
      "relation": item.relation
    }
    filteredList.push(tmp);
  })

  // 记录当前选中的微服务异味信息
  const item = props.antipattern;

  //删除 item 中的无用属性
  delete item.id;
  delete item.isDelete;

  //向 item 中增加新属性：关联异味信息
  item.relatedAntiPatterns = filteredList;

  // JSON Object → JSON String
  const json = JSON.stringify(item)

  // 复制到剪切板
  props.copyAsJson(json, item.name);
}
//endregion


//region 初始化弹窗信息
const antiPatterns = ref([]);
const tableData = ref([]);
const Init = async () => {
  // 从数据库获取全部异味信息
  let res = await listUsingGet({});
  res.data?.forEach((antipatternInfoVO) => {
    antiPatterns.value.push(antipatternInfoVO);
  })

  // 记录关联异味信息和全部异味信息
  const relatedAntipatterns = props.relatedAntipatternList;
  const antipatterns = antiPatterns.value;
  // console.log("relatedAntipatterns");
  // console.log(relatedAntipatterns);
  // console.log("antipatterns");
  // console.log(antipatterns);
  // 相当于在前端做一遍表连接，拼接两张表，进而获得关联异味信息的描述
  const filterList = [];
  for (const item of relatedAntipatterns) {
    for (const elem of antipatterns) {
      if (item.relatedAntiPatternName === elem.name) {
        let tmp = {
          name: '',
          description: '',
          relation: '',
        };
        tmp.name = elem.name;
        tmp.relation = item.relation;
        tmp.description = elem.description;
        filterList.push(tmp);
      }
    }
  }
  // console.log("filterList")
  // console.log(filterList)
  filterList.forEach((item) => {
    tableData.value.push(item);
  })
  // console.log(tableData)
}
Init();
//endregion


</script>


<style scoped>
*{
  font-size: 18px;
}
</style>
